import{_ as t,o as s,c as a,ag as o}from"./chunks/framework.DPTJCqgd.js";const y=JSON.parse('{"title":"Run DSH behind a network proxy","description":"","frontmatter":{"editSource":"docs/user/guide/network-proxy.md","editSourceUrl":"https://github.com/Bestbbb/deepseek-harness-desktop/edit/2847c75ea844b05f9d8adca865940856f1286c8c/docs/user/guide/network-proxy.md"},"headers":[],"relativePath":"en/guide/network-proxy.md","filePath":"en/guide/network-proxy.md"}'),i={name:"en/guide/network-proxy.md"};function r(n,e,h,d,l,c){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="run-dsh-behind-a-network-proxy" tabindex="-1">Run DSH behind a network proxy <a class="header-anchor" href="#run-dsh-behind-a-network-proxy" aria-label="Permalink to &quot;Run DSH behind a network proxy&quot;">​</a></h1><p>DSH routes its outbound requests — model calls, web search, page fetches, and MCP servers over HTTP — through the proxy named by the standard proxy environment variables. It reads them at launch; nothing else needs configuring. A few paths stay direct by design or by runtime limit, listed under &quot;What stays direct&quot; below.</p><h2 id="export-the-variables" tabindex="-1">Export the variables <a class="header-anchor" href="#export-the-variables" aria-label="Permalink to &quot;Export the variables&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HTTPS_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:7890</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HTTP_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:7890</span></span></code></pre></div><p>Put both lines in your shell profile so every <code>dsh</code> invocation inherits them, or in <code>$DSH_HOME/.env</code> (<code>~/.dsh/.env</code> by default) next to your API key; an exported variable always wins over that file. A project&#39;s own <code>.env</code> cannot set them: it arrives with <code>git clone</code>, and DSH refuses to start rather than let a repository decide where your traffic goes.</p><p>A proxy that needs credentials takes them in the URL: <code>http://user:password@proxy.example:8080</code>. DSH never prints the URL back: a diagnostic names the variable it rejected, so neither the username nor the password appears anywhere.</p><h2 id="why-your-browser-is-proxied-but-your-terminal-is-not" tabindex="-1">Why your browser is proxied but your terminal is not <a class="header-anchor" href="#why-your-browser-is-proxied-but-your-terminal-is-not" aria-label="Permalink to &quot;Why your browser is proxied but your terminal is not&quot;">​</a></h2><p>This is the most common surprise, and it is not specific to DSH. There is no single &quot;system proxy&quot; that all software obeys — there are three unrelated mechanisms:</p><table tabindex="0"><thead><tr><th>Mechanism</th><th>Who follows it</th></tr></thead><tbody><tr><td>The operating system&#39;s proxy settings</td><td>Safari, most native macOS apps, Chrome and Edge</td></tr><tr><td>The <code>HTTP_PROXY</code> / <code>HTTPS_PROXY</code> environment variables</td><td><code>curl</code>, <code>git</code>, <code>npm</code>, <code>pip</code>, and DSH</td></tr><tr><td>TUN mode (a virtual network interface)</td><td>Everything, transparently</td></tr></tbody></table><p>The &quot;system proxy&quot; switch in a proxy application such as Clash writes only the first one. Browsers pick it up; command-line tools never see it. That is why exporting the variables is a separate step, and why turning on TUN mode makes both work without any variables at all.</p><p>DSH does not read the operating system&#39;s proxy settings. Export the variables, or use TUN mode.</p><h2 id="choose-what-stays-direct" tabindex="-1">Choose what stays direct <a class="header-anchor" href="#choose-what-stays-direct" aria-label="Permalink to &quot;Choose what stays direct&quot;">​</a></h2><p><code>NO_PROXY</code> lists hosts to reach directly:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NO_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">internal.example.com,.corp.example.com,registry.local</span></span></code></pre></div><p>An entry names a host and matches it together with every subdomain under it: <code>NO_PROXY=example.com</code> also sends <code>api.example.com</code> direct. A leading <code>.</code> or <code>*.</code> is accepted and means the same thing. An entry may carry a <code>:port</code>, and <code>*</code> bypasses everything.</p><p><strong>CIDR ranges do not work.</strong> An operating system bypass list often contains entries like <code>10.0.0.0/8</code> or <code>192.168.0.0/16</code>; copying those into <code>NO_PROXY</code> has no effect. Use host names or domain suffixes instead.</p><p>You do not need to list <code>localhost</code> or <code>127.0.0.1</code>. DSH always bypasses loopback, because its own Web UI and local servers would otherwise route through the proxy and loop.</p><h2 id="limits-worth-knowing" tabindex="-1">Limits worth knowing <a class="header-anchor" href="#limits-worth-knowing" aria-label="Permalink to &quot;Limits worth knowing&quot;">​</a></h2><p><strong>SOCKS proxies are not supported.</strong> A <code>socks5://</code> value is reported at startup and skipped, and DSH connects directly for the scheme that named it — setting <code>HTTPS_PROXY=socks5://…</code> alongside a usable <code>HTTP_PROXY</code> leaves <code>https:</code> direct rather than borrowing the HTTP proxy. Point the variables at your proxy application&#39;s HTTP port instead — most expose both, and the HTTP one is usually a neighbouring port number.</p><p><strong><code>ALL_PROXY</code> alone is enough.</strong> DSH falls back to it for both schemes, even though Node and curl differ on this. Setting <code>HTTPS_PROXY</code> explicitly is still clearer.</p><p><strong>A TLS-intercepting corporate proxy needs its certificate.</strong> If requests fail with a certificate error once the proxy is reachable, point Node at your organisation&#39;s CA bundle before launching:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NODE_EXTRA_CA_CERTS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/path/to/corporate-ca.pem</span></span></code></pre></div><p>Node reads that variable only at process start, so export it before running <code>dsh</code>.</p><p><strong>Tools DSH runs for you follow the same proxy.</strong> Commands in the bash tool, <code>git</code>, <code>gh</code>, and MCP servers started as child processes all inherit these variables. A child that is itself a Node program honors them only on Node 22.21 or later; an older Node connects directly. If one of your proxy variables holds a value DSH rejected — a SOCKS URL, say — Node-based tools also connect directly rather than fail to start, while <code>curl</code> and <code>git</code> still read that value.</p><p><strong>A password in the proxy URL reaches those tools too.</strong> <code>HTTPS_PROXY=http://alice:s3cret@proxy.example:8080</code> is a normal environment variable, so every command DSH runs — including the ones the model writes — can read it, and a command that prints its environment puts the password in output that is kept. This is how the variable already behaves for everything else in your shell. If that matters, give the proxy a credential-free entry point, or authenticate it some other way than in the URL.</p><h2 id="what-stays-direct" tabindex="-1">What stays direct <a class="header-anchor" href="#what-stays-direct" aria-label="Permalink to &quot;What stays direct&quot;">​</a></h2><p>Not every request DSH makes goes through the proxy:</p><ul><li><strong>Anything on this machine.</strong> Loopback is always direct: <code>localhost</code>, the whole <code>127.0.0.0/8</code> range, <code>::1</code>, and <code>0.0.0.0</code>. A proxy cannot usefully reach a service that only listens locally.</li><li><strong>Code the model writes.</strong> The workflow and code-runtime workers never receive the proxy settings, so a script the model authors cannot read a proxy URL that may carry a password. Such a script reaches the network only if it configures that itself.</li><li><strong>Usage telemetry.</strong> The OTLP exporter uses Node&#39;s own HTTP client rather than the one a proxy configures, so telemetry connects directly and simply fails where direct egress is blocked. Nothing you do in DSH depends on it. Set <code>DSH_TELEMETRY_MODE=DISABLED</code> to turn it off entirely.</li><li><strong><code>web_fetch</code> to a literal private address.</strong> A URL naming an address like <code>http://10.0.0.5/</code> is refused rather than handed to the proxy, the same refusal it gets with no proxy configured.</li></ul><h2 id="check-that-it-worked" tabindex="-1">Check that it worked <a class="header-anchor" href="#check-that-it-worked" aria-label="Permalink to &quot;Check that it worked&quot;">​</a></h2><p>Ask the agent to fetch a page and watch your proxy application&#39;s connection log:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> headless</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;fetch https://example.com and tell me the page title&quot;</span></span></code></pre></div><p>If the request does not appear there, confirm the variables survive into DSH&#39;s own environment:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> proxy</span></span></code></pre></div>`,33)])])}const u=t(i,[["render",r]]);export{y as __pageData,u as default};
